-- 004: Atomic counter sales, cash collection, FIFO queue, and staff order reads.
-- Run after 003. Payment, stock, audit, and queue changes commit or roll back together.
begin;

create table if not exists public."OrderAuditEvent" (
  "OrderAuditEventID" bigint generated by default as identity primary key,
  "OrderID" bigint not null,
  "PreviousStatus" text,
  "NewStatus" text not null,
  "EmployeeID" bigint,
  "CreatedAt" timestamptz not null default now(),
  "Details" jsonb not null default '{}'::jsonb
);
alter table public."OrderAuditEvent" enable row level security;
revoke all on public."OrderAuditEvent" from anon, authenticated;

create or replace function public.esmiringkape_order_status_audit()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_event jsonb;
  v_columns text;
  v_values text;
  v_missing_required boolean;
begin
  if new."Status" is not distinct from old."Status" then return new; end if;
  insert into public."OrderAuditEvent" ("OrderID", "PreviousStatus", "NewStatus", "EmployeeID")
  values (new."OrderID", old."Status", new."Status", public.esmiringkape_current_employee_id());

  -- Write to the legacy history table when its existing columns support the event.
  v_event := jsonb_build_object(
    'OrderID', new."OrderID", 'Status', new."Status", 'NewStatus', new."Status",
    'PreviousStatus', old."Status", 'OldStatus', old."Status",
    'ChangedAt', clock_timestamp(), 'CreatedAt', clock_timestamp(), 'HistoryDate', clock_timestamp(),
    'EmployeeID', public.esmiringkape_current_employee_id(),
    'ChangedByEmployeeID', public.esmiringkape_current_employee_id()
  );
  select exists (
    select 1 from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = 'OrderStatusHistory'
      and c.is_nullable = 'NO' and c.column_default is null and c.is_identity = 'NO'
      and c.column_name not in (
        'OrderID', 'Status', 'NewStatus', 'PreviousStatus', 'OldStatus', 'ChangedAt', 'CreatedAt',
        'HistoryDate', 'EmployeeID', 'ChangedByEmployeeID'
      )
  ) into v_missing_required;
  if v_missing_required then return new; end if;

  select string_agg(format('%I', c.column_name), ', ' order by c.ordinal_position),
         string_agg(format('r.%I', c.column_name), ', ' order by c.ordinal_position)
  into v_columns, v_values
  from information_schema.columns c
  where c.table_schema = 'public' and c.table_name = 'OrderStatusHistory'
    and c.column_name in (
      'OrderID', 'Status', 'NewStatus', 'PreviousStatus', 'OldStatus', 'ChangedAt', 'CreatedAt',
      'HistoryDate', 'EmployeeID', 'ChangedByEmployeeID'
    )
    and c.is_generated = 'NEVER' and c.is_identity = 'NO';
  if v_columns is not null then
    execute format(
      'insert into public."OrderStatusHistory" (%s) select %s from jsonb_populate_record(null::public."OrderStatusHistory", $1) r',
      v_columns, v_values
    ) using v_event;
  end if;
  return new;
end;
$$;

drop trigger if exists order_status_audit on public."Order";
create trigger order_status_audit
after update of "Status" on public."Order"
for each row execute function public.esmiringkape_order_status_audit();

create or replace function public.esmiringkape_staff_order_json(p_order_id bigint)
returns jsonb
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'order_id', o."OrderID",
    'order_number', o."OrderID"::text,
    'ticket_number', o."OrderID"::text,
    'status', case when lower(o."Status") = 'pending'
      and lower(coalesce(p."PaymentStatus", 'unpaid')) <> 'paid' then 'Awaiting Payment'
      when lower(o."Status") = 'pending' then 'Waiting'
      else o."Status" end,
    'total', coalesce(o."TotalAmount", 0),
    'subtotal', coalesce(o."Subtotal", o."TotalAmount", 0),
    'discount_total', coalesce(o."DiscountAmount", 0),
    'tax_total', coalesce(o."TaxAmount", 0),
    'payment_status', coalesce(p."PaymentStatus", 'Unpaid'),
    'amount_paid', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then coalesce(p."AmountApplied", p."AmountPaid", 0) else 0 end,
    'refunded_amount', coalesce(p."RefundedAmount", 0),
    'net_amount', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then greatest(0, coalesce(p."AmountApplied", p."AmountPaid", 0) - coalesce(p."RefundedAmount", 0)) else 0 end,
    'amount_due', greatest(0, coalesce(o."TotalAmount", 0) - case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then coalesce(p."AmountApplied", p."AmountPaid", 0) else 0 end),
    'payment_method', p."PaymentMethod",
    'cash_tendered', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then p."CashTendered" end,
    'change_given', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then p."ChangeGiven" end,
    'cashier', coalesce(cashier."FullName", staff."FullName"),
    'shop_name', coalesce((select s."SettingValue" from public."ShopSetting" s where s."SettingKey" = 'shop_name'), 'Esmiringkape'),
    'receipt_footer', (select s."SettingValue" from public."ShopSetting" s where s."SettingKey" = 'receipt_footer'),
    'created_at', o."OrderDate",
    'guest_name', coalesce(o."PickupName", customer."FullName"),
    'order_type', coalesce(o."OrderType", 'guest'),
    'queue_entered_at', o."QueueEnteredAt",
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_id', oi."ItemID",
        'item_name', coalesce(oi."ItemNameSnapshot", mi."ItemName", 'Item'),
        'quantity', oi."Quantity",
        'unit_price', coalesce(oi."UnitPrice", mi."Price", 0),
        'line_total', coalesce(oi."LineTotal", oi."Quantity" * coalesce(oi."UnitPrice", mi."Price", 0))
      ) order by oi."ItemID")
      from public."OrderItem" oi
      left join public."MenuItems" mi on mi."ItemID" = oi."ItemID"
      where oi."OrderID" = o."OrderID"
    ), '[]'::jsonb)
  )
  from public."Order" o
  left join public.customers customer on customer."customerID" = o."CustomerID"
  left join public."Employee" staff on staff."EmployeeID" = o."EmployeeID"
  left join lateral (
    select payment.* from public."Payment" payment
    where payment."OrderID" = o."OrderID"
    order by payment."PaymentDate" desc nulls last
    limit 1
  ) p on true
  left join public."Employee" cashier on cashier."EmployeeID" = p."VerifiedByEmployeeID"
  where o."OrderID" = p_order_id;
$$;

create or replace function public.esmiringkape_confirm_cash_payment(p_order_id bigint, p_cash_tendered numeric)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_employee_id bigint;
  v_order public."Order"%rowtype;
  v_total numeric(12,2);
  v_paid boolean;
  v_payment_tid tid;
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier') then
    raise exception 'Cashier access required' using errcode = '42501';
  end if;
  v_employee_id := public.esmiringkape_current_employee_id();
  select * into v_order from public."Order" where "OrderID" = p_order_id for update;
  if not found then raise exception 'Order not found' using errcode = 'P0002'; end if;
  if lower(v_order."Status") = 'cancelled' then raise exception 'Cancelled orders cannot be paid'; end if;

  select exists(select 1 from public."Payment" where "OrderID" = p_order_id and lower("PaymentStatus") = 'paid')
    into v_paid;
  if v_paid then
    update public."Order"
      set "QueueEnteredAt" = coalesce("QueueEnteredAt", clock_timestamp()),
          "Status" = case when lower("Status") in ('pending', 'waiting', 'awaiting payment') then 'Pending' else "Status" end
    where "OrderID" = p_order_id;
    return public.esmiringkape_staff_order_json(p_order_id);
  end if;

  select "TotalAmount" into v_total from public."Order" where "OrderID" = p_order_id;
  if v_total is null or v_total <= 0 then raise exception 'Order has no payable items'; end if;
  if p_cash_tendered is null or p_cash_tendered < v_total then
    raise exception 'Cash received must cover %', v_total using errcode = '22023';
  end if;

  perform public.esmiringkape_deduct_order_stock(p_order_id, v_employee_id);
  select ctid into v_payment_tid
  from public."Payment"
  where "OrderID" = p_order_id and lower(coalesce("PaymentStatus", 'unpaid')) <> 'paid'
  order by "PaymentDate" nulls first
  limit 1 for update;

  if v_payment_tid is null then
    insert into public."Payment" (
      "OrderID", "PaymentMethod", "AmountPaid", "AmountApplied", "CashTendered", "ChangeGiven",
      "PaymentDate", "PaymentStatus", "VerifiedByEmployeeID"
    ) values (
      p_order_id, 'Cash', v_total, v_total, p_cash_tendered, p_cash_tendered - v_total,
      clock_timestamp(), 'Paid', v_employee_id
    );
  else
    update public."Payment"
      set "PaymentMethod" = 'Cash', "AmountPaid" = v_total, "AmountApplied" = v_total,
          "CashTendered" = p_cash_tendered, "ChangeGiven" = p_cash_tendered - v_total,
          "PaymentDate" = clock_timestamp(), "PaymentStatus" = 'Paid',
          "VerifiedByEmployeeID" = v_employee_id
      where ctid = v_payment_tid;
  end if;

  update public."Order"
    set "QueueEnteredAt" = coalesce("QueueEnteredAt", clock_timestamp()),
        "Status" = case when lower("Status") in ('pending', 'waiting', 'awaiting payment') then 'Pending' else "Status" end
  where "OrderID" = p_order_id;
  return public.esmiringkape_staff_order_json(p_order_id);
end;
$$;

create or replace function public.esmiringkape_quote_counter_sale(p_items jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_count integer;
  v_distinct_count integer;
  v_subtotal numeric(12,2);
  v_discount_rate numeric(7,4);
  v_tax_rate numeric(7,4);
  v_discount numeric(12,2);
  v_tax numeric(12,2);
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier') then
    raise exception 'Cashier access required' using errcode = '42501';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 30 then
    raise exception 'Use 1 to 30 items per order' using errcode = '22023';
  end if;
  select count(*), count(distinct x.item_id), sum(mi."Price"::numeric * x.quantity)::numeric(12,2)
    into v_count, v_distinct_count, v_subtotal
  from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer)
  join public."MenuItems" mi on mi."ItemID" = x.item_id and mi."Available" is true
  where x.quantity between 1 and 99;
  if v_count <> jsonb_array_length(p_items) or v_count <> v_distinct_count then
    raise exception 'An item is unavailable, duplicated, or has an invalid quantity' using errcode = '22023';
  end if;
  select least(100, coalesce(sum("RatePercent"), 0)) into v_discount_rate from public."DiscountRule" where "IsActive";
  select coalesce(sum("RatePercent"), 0) into v_tax_rate from public."TaxRule" where "IsActive";
  v_discount := round(v_subtotal * v_discount_rate / 100, 2);
  v_tax := round((v_subtotal - v_discount) * v_tax_rate / 100, 2);
  return jsonb_build_object(
    'subtotal', v_subtotal, 'discount_total', v_discount, 'tax_total', v_tax,
    'total', v_subtotal - v_discount + v_tax,
    'items', (select jsonb_agg(jsonb_build_object('item_id', mi."ItemID", 'item_name', mi."ItemName", 'quantity', x.quantity, 'unit_price', mi."Price", 'line_total', round(mi."Price" * x.quantity, 2)) order by mi."ItemID")
      from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer)
      join public."MenuItems" mi on mi."ItemID" = x.item_id)
  );
end;
$$;

create or replace function public.esmiringkape_complete_counter_sale(
  p_idempotency_key uuid,
  p_items jsonb,
  p_customer_id bigint,
  p_pickup_name text,
  p_cash_tendered numeric
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_employee_id bigint;
  v_order_id bigint;
  v_subtotal numeric(12,2);
  v_item_count integer;
  v_distinct_count integer;
  v_line record;
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier') then
    raise exception 'Cashier access required' using errcode = '42501';
  end if;
  if p_idempotency_key is null then raise exception 'Idempotency key required'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 30 then
    raise exception 'Use 1 to 30 items per order' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));
  select "OrderID" into v_order_id from public."SaleIdempotency" where "IdempotencyKey" = p_idempotency_key;
  if v_order_id is not null then return public.esmiringkape_staff_order_json(v_order_id); end if;

  select count(*), count(distinct x.item_id),
         sum(mi."Price"::numeric * x.quantity)::numeric(12,2)
    into v_item_count, v_distinct_count, v_subtotal
  from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer)
  join public."MenuItems" mi on mi."ItemID" = x.item_id and mi."Available" is true
  where x.quantity between 1 and 99;
  if v_item_count <> jsonb_array_length(p_items) or v_item_count <> v_distinct_count then
    raise exception 'An item is unavailable, duplicated, or has an invalid quantity' using errcode = '22023';
  end if;
  if p_customer_id is not null and not exists(select 1 from public.customers where "customerID" = p_customer_id) then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;

  v_employee_id := public.esmiringkape_current_employee_id();
  insert into public."Order" (
    "CustomerID", "OrderDate", "Status", "EmployeeID", "PickupName", "OrderType", "Subtotal", "TotalAmount"
  ) values (
    p_customer_id, clock_timestamp(), 'Pending', v_employee_id, nullif(trim(p_pickup_name), ''), 'counter', v_subtotal, v_subtotal
  ) returning "OrderID" into v_order_id;

  for v_line in select * from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer) order by item_id loop
    insert into public."OrderItem" ("OrderID", "ItemID", "Quantity")
    values (v_order_id, v_line.item_id, v_line.quantity);
  end loop;
  perform public.esmiringkape_calculate_order_totals(v_order_id);
  perform public.esmiringkape_confirm_cash_payment(v_order_id, p_cash_tendered);
  insert into public."SaleIdempotency" ("IdempotencyKey", "OrderID") values (p_idempotency_key, v_order_id);
  return public.esmiringkape_staff_order_json(v_order_id);
end;
$$;

create or replace function public.esmiringkape_staff_list_orders()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier', 'barista') then
    raise exception 'Staff access required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(public.esmiringkape_staff_order_json(o."OrderID") order by o."OrderDate" desc, o."OrderID" desc)
    from public."Order" o
  ), '[]'::jsonb);
end;
$$;

create or replace function public.esmiringkape_staff_queue()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier', 'barista') then
    raise exception 'Staff access required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(public.esmiringkape_staff_order_json(o."OrderID") order by o."QueueEnteredAt", o."OrderID")
    from public."Order" o
    where o."QueueEnteredAt" is not null
      and lower(o."Status") in ('pending', 'waiting', 'preparing', 'ready')
      and exists(select 1 from public."Payment" p where p."OrderID" = o."OrderID" and lower(p."PaymentStatus") = 'paid')
  ), '[]'::jsonb);
end;
$$;

create or replace function public.esmiringkape_claim_next_order()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_order_id bigint;
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier', 'barista') then
    raise exception 'Staff access required' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('esmiringkape_next_queue_order'));
  select o."OrderID" into v_order_id
  from public."Order" o
  where o."QueueEnteredAt" is not null and lower(o."Status") in ('pending', 'waiting')
    and exists(select 1 from public."Payment" p where p."OrderID" = o."OrderID" and lower(p."PaymentStatus") = 'paid')
  order by o."QueueEnteredAt" asc, o."OrderID" asc
  limit 1
  for update of o skip locked;
  if v_order_id is null then return null; end if;
  update public."Order" set "Status" = 'Preparing' where "OrderID" = v_order_id;
  return public.esmiringkape_staff_order_json(v_order_id);
end;
$$;

create or replace function public.esmiringkape_update_preparation_status(p_order_id bigint, p_status text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_order public."Order"%rowtype;
  v_next text;
  v_current text;
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier', 'barista') then
    raise exception 'Staff access required' using errcode = '42501';
  end if;
  v_next := case lower(trim(p_status))
    when 'waiting' then 'Pending'
    when 'preparing' then 'Preparing'
    when 'ready' then 'Ready'
    when 'completed' then 'Completed'
    else null end;
  if v_next is null then raise exception 'Unsupported preparation status' using errcode = '22023'; end if;
  select * into v_order from public."Order" where "OrderID" = p_order_id for update;
  if not found then raise exception 'Order not found' using errcode = 'P0002'; end if;
  if lower(v_order."Status") in ('cancelled', 'completed') then raise exception 'Order is no longer active'; end if;
  if v_order."QueueEnteredAt" is null or not exists (
    select 1 from public."Payment" p where p."OrderID" = p_order_id and lower(p."PaymentStatus") = 'paid'
  ) then raise exception 'Payment must be confirmed before preparation'; end if;

  v_current := case when lower(v_order."Status") = 'pending' then 'waiting' else lower(v_order."Status") end;
  if lower(v_next) <> v_current and not (
    (v_current = 'preparing' and v_next = 'Ready') or
    (v_current = 'ready' and v_next = 'Completed')
  ) then raise exception 'Invalid preparation status transition: % to %', v_current, v_next using errcode = '22023'; end if;
  update public."Order" set "Status" = v_next where "OrderID" = p_order_id;
  return public.esmiringkape_staff_order_json(p_order_id);
end;
$$;

grant select on public."Order", public."OrderItem", public."Payment", public."OrderStatusHistory" to authenticated;
create policy order_staff_read on public."Order" for select to authenticated
  using (public.esmiringkape_staff_role() in ('admin', 'cashier', 'barista'));
create policy order_item_staff_read on public."OrderItem" for select to authenticated
  using (public.esmiringkape_staff_role() in ('admin', 'cashier', 'barista'));
create policy payment_staff_read on public."Payment" for select to authenticated
  using (public.esmiringkape_staff_role() in ('admin', 'cashier', 'barista'));
create policy order_history_staff_read on public."OrderStatusHistory" for select to authenticated
  using (public.esmiringkape_staff_role() in ('admin', 'cashier', 'barista'));

revoke all on function public.esmiringkape_staff_order_json(bigint) from public, anon, authenticated;
revoke all on function public.esmiringkape_confirm_cash_payment(bigint, numeric) from public, anon;
revoke all on function public.esmiringkape_quote_counter_sale(jsonb) from public, anon;
revoke all on function public.esmiringkape_complete_counter_sale(uuid, jsonb, bigint, text, numeric) from public, anon;
revoke all on function public.esmiringkape_staff_list_orders() from public, anon;
revoke all on function public.esmiringkape_staff_queue() from public, anon;
revoke all on function public.esmiringkape_claim_next_order() from public, anon;
revoke all on function public.esmiringkape_update_preparation_status(bigint, text) from public, anon;
grant execute on function public.esmiringkape_confirm_cash_payment(bigint, numeric) to authenticated;
grant execute on function public.esmiringkape_quote_counter_sale(jsonb) to authenticated;
grant execute on function public.esmiringkape_complete_counter_sale(uuid, jsonb, bigint, text, numeric) to authenticated;
grant execute on function public.esmiringkape_staff_list_orders() to authenticated;
grant execute on function public.esmiringkape_staff_queue() to authenticated;
grant execute on function public.esmiringkape_claim_next_order() to authenticated;
grant execute on function public.esmiringkape_update_preparation_status(bigint, text) to authenticated;

commit;

